1	import { finding } from '../../../engine/checks/helpers/findings.mjs';
2	import { stripComments } from '../../../engine/checks/helpers/code-scanning.mjs';
3	import { FREQUENCIES } from '../../claudinite-tasks/calendar.mjs';
4	import { MODEL_FAMILIES } from '../../claudinite-tasks/model-map.mjs';
5	import { OUTCOMES, LEGACY_OUTCOMES, SIGNAL_NAMES } from '../../claudinite-tasks/task-contract.mjs';
6	
7	// Every scheduler task is a `tasks/<name>/task.mjs` whose default export carries
8	// the full declaration contract (per-project-scheduling DESIGN §1) with legal
9	// enum values. This asserts that shape statically at author time — the executor
10	// and scheduler validate the same contract at run time (task-contract.mjs), so
11	// an illegal frequency/model/outcome, or a missing field, is caught here first.
12	//
13	// RELEVANCE FIRST (engine/checks/README.md): gated on a `tasks/<name>/task.mjs`
14	// existing, so the check is inert on any repo without tasks. Static text over
15	// the self-contained module (task.mjs imports nothing), keyed off the canonical
16	// enum lists so the legal values never drift from the runtime validator.
17	const TASK_MJS = /(^|\/)tasks\/[^/]+\/task\.mjs$/;
18	
19	// A file that only re-exports another module declares nothing of its own — a
20	// legacy-path shim left behind by a relocation is the shape. The declaration it
21	// names is scanned where it actually lives, so judging the shim would report the
22	// same task twice and fail it on text it does not carry.
23	const isReExport = (text) => {
24	  const code = text.split('\n').map((l) => l.trim()).filter((l) => l && !l.startsWith('//'));
25	  return code.length > 0 && code.every((l) => /^(import|export)\b.*\bfrom\b/.test(l) || /^import\s+['"]/.test(l));
26	};
27	
28	// The value of a top-level `key: 'value'` string field, or null if absent.
29	const strField = (text, key) => {
30	  const m = new RegExp(`\\b${key}:\\s*['"]([^'"]+)['"]`).exec(text);
31	  return m ? m[1] : null;
32	};
33	
34	const rule = {
35	  id: 'task-declaration-shape',
36	  severity: 'blocking',
37	  description: 'A tasks/<name>/task.mjs default-exports the full task contract (id, frequency, precondition_signals, agent_model, expected_outcome, agent_instructions, precondition) with legal enum values; a pr task pairs its ceiling with a automerge policy, an agentic task bounds its run with agent_execution_timeout, and any code_work carries a timeout and stays task-local',
38	  doc: 'packs/claudinite-tasks/README.md',
39	  why: 'the scheduler run and executor read agent_model/expected_outcome/frequency from this file, not the work item — an illegal or missing value means a task never fires, fires wrong, or writes past its ceiling',
40	
41	  run(ctx) {
42	    const out = [];
43	    for (const file of ctx.files.filter((f) => TASK_MJS.test(f))) {
44	      const text = ctx.read(file);
45	      if (text === null || isReExport(text)) continue;
46	      const flag = (what, fix) => out.push(finding(rule, { file, what, fix }));
47	      const model = strField(text, 'agent_model');
48	
49	      if (!/export\s+default\s*\{/.test(text)) {
50	        flag('does not default-export a declaration object', 'export default { id, frequency, precondition_signals, agent_model, expected_outcome, agent_instructions, precondition }');
51	        continue;
52	      }
53	      const enumField = (key, legal) => {
54	        const v = strField(text, key);
55	        if (v === null) flag(`declares no "${key}"`, `add "${key}": one of ${legal.join(', ')}`);
56	        else if (!legal.includes(v)) flag(`"${key}" is "${v}", not a legal value`, `use one of: ${legal.join(', ')}`);
57	      };
58	      enumField('frequency', FREQUENCIES);
59	      enumField('agent_model', MODEL_FAMILIES);
60	
61	      // expected_outcome takes the ceiling/policy split, with the retired
62	      // one-word ceilings an ADVISORY rename like the code-work names below:
63	      // the runtime normalizes them at the door forever, so a member's vendor
64	      // refresh must not turn its CI red over a declaration nobody edited.
65	      const outcome = strField(text, 'expected_outcome');
66	      const hasMayAutomerge = /\bautomerge:\s*/.test(stripComments(text));
67	      if (outcome === null) {
68	        flag('declares no "expected_outcome"', `add "expected_outcome": one of ${OUTCOMES.join(', ')}`);
69	      } else if (LEGACY_OUTCOMES[outcome] !== undefined) {
70	        out.push(finding(rule, {
71	          file,
72	          severity: 'advisory',
73	          what: `declares the legacy outcome ceiling "${outcome}"`,
74	          fix: `write the pair it normalizes to: expected_outcome: 'pr', automerge: '${LEGACY_OUTCOMES[outcome]}' — and consider a narrower policy than '${LEGACY_OUTCOMES[outcome]}' (a list of diff classes, e.g. ['comment-only-changes'])`,
75	        }));
76	      } else if (!OUTCOMES.includes(outcome)) {
77	        flag(`"expected_outcome" is "${outcome}", not a legal value`, `use one of: ${OUTCOMES.join(', ')}`);
78	      } else if (outcome === 'pr' && !hasMayAutomerge) {
79	        flag('a "pr" task declares no "automerge"', 'say what may land unreviewed: "nothing", "anything", or a list of diff classes, e.g. ["comment-only-changes", "readme-changes"]');
80	      } else if (outcome === 'none' && hasMayAutomerge) {
81	        flag('a "none" task declares "automerge"', 'drop it — a task that opens no pull request has nothing to merge; or set expected_outcome: "pr"');
82	      }
83	
84	      if (!/\bid:\s*['"]/.test(text)) flag('declares no string "id"', 'add "id": the task name (matching its directory)');
85	      // agent_instructions is required only for an agentic task (agent_model !==
86	      // 'none') — that's the worker file the agent reads. A `none` task runs no
87	      // agent, so the field is not applicable.
88	      if (model !== 'none' && !/\bagent_instructions:\s*['"]/.test(text)) {
89	        flag('an agentic task (agent_model !== "none") declares no string "agent_instructions"', 'add "agent_instructions": the worker file beside task.mjs (e.g. "task.md")');
90	      }
91	      if (!/\bprecondition_signals:\s*\[/.test(text)) {
92	        flag('declares no "precondition_signals" array', `add "precondition_signals": an array of ${SIGNAL_NAMES.join(', ')}`);
93	      }
94	      if (!/\bprecondition\s*[:(]/.test(text)) {
95	        flag('declares no "precondition" function', 'add a precondition(signals, config) that returns { run, reason, context? }');
96	      }
97	
98	      // The code-work/timeout guards (task-code-work DESIGN §2). Numeric presence is
99	      // a cheap `<key>: <digit>` regex, matching the runtime contract. TWO
100	      // generations of legacy field names still satisfy the contract — the loader
101	      // normalizes both — but each earns its own rename finding so the fleet
102	      // converges on the canonical names.
103	      const hasNum = (...keys) => keys.some((key) => new RegExp(`\\b${key}:\\s*\\d`).test(text));
104	      const LEGACY_CODE_WORK = [
105	        { field: 'agent_preprocessing', timeout: 'agent_preprocessing_timeout' },
106	        { field: 'prework', timeout: 'prework_timeout' },
107	      ];
108	      const legacyDeclared = LEGACY_CODE_WORK.filter(({ field }) => new RegExp(`\\b${field}:\\s*['"]`).test(text));
109	      const hasCodeWork = /\bcode_work:\s*['"]/.test(text) || legacyDeclared.length > 0;
110	      for (const { field, timeout } of legacyDeclared) {
111	        // ADVISORY, deliberately, on a blocking rule: the legacy names still
112	        // satisfy the runtime contract (normalized at load), and a member's
113	        // vendor refresh must not turn its CI red over files nothing has renamed
114	        // yet. This finding IS the durable driver of the rename — it names the
115	        // exact edit and does not age out, which is why neither rename ships a
116	        // migration note.
117	        out.push(finding(rule, {
118	          file,
119	          severity: 'advisory',
120	          what: `declares code_work under the legacy name "${field}"`,
121	          fix: `rename "${field}" → "code_work" and "${timeout}" → "code_work_timeout" (the two phases of task execution are code-work, then agentic-work — neither is named for the other)`,
122	        }));
123	      }
124	      // The ordering field's rename. ADVISORY for the same reason as the code-work rename above:
125	      // the runtime normalizes it at the door, so a member's own task file keeps working and its
126	      // CI must not go red over a declaration nobody has edited. Worth making because the bare
127	      // preposition invited reading the field as a time — it is not one; it names task ids, and
128	      // what it steers is when the item is scheduled onto an executor.
129	      //
130	      // The regex is anchored on a NON-word character before the key so it cannot match the
131	      // canonical spelling's own tail.
132	      if (/(?<![\w.])after:\s*\[/.test(text)) {
133	        out.push(finding(rule, {
134	          file,
135	          severity: 'advisory',
136	          what: 'declares its ordering under the legacy name "after"',
137	          fix: 'rename "after" to "schedule_after" (it names task ids, not a time — what it steers is when this item is scheduled onto an executor)',
138	        }));
139	      }
140	      // `session_scope` lost its last reader with the slot scheduler (#974): the
141	      // queue routes a hand-off by `invocation_endpoint`, and nothing anywhere
142	      // asks a task what its scope is. ADVISORY, like the code-work rename above and
143	      // for the same reason — the field still VALIDATES, so a member's vendor
144	      // refresh must not turn its CI red over a declaration nobody has edited yet;
145	      // this only keeps the dead field visible until it is dropped.
146	      // Comments stripped: this rule's own remedy names the field, and so does any
147	      // note explaining why a task stopped declaring one.
148	      if (/\bsession_scope:\s*['"]/.test(stripComments(text))) {
149	        out.push(finding(rule, {
150	          file,
151	          severity: 'advisory',
152	          what: 'declares "session_scope", which nothing reads',
153	          fix: 'drop it — reach is a property of which endpoint the hand-off calls, so a task needing wider access declares "invocation_endpoint": <a key in the repo\'s taskScheduler.agenticTaskInvocationEndpoints> instead',
154	        }));
155	      }
156	      if (model && MODEL_FAMILIES.includes(model) && model !== 'none' && !hasNum('agent_execution_timeout')) {
157	        flag('an agentic task (agent_model !== "none") declares no numeric "agent_execution_timeout"', 'add "agent_execution_timeout": seconds bounding the agentic run');
158	      }
159	      if (model === 'none' && !hasCodeWork) {
160	        flag('an agentless task (agent_model: "none") declares no "code_work"', 'add "code_work" (a none task does its work in that subprocess) — or give the task an agent_model');
161	      }
162	      if (hasCodeWork) {
163	        const prep = LEGACY_CODE_WORK.reduce((found, { field }) => found ?? strField(text, field), strField(text, 'code_work'));
164	        if (prep && (/(^|\s)\//.test(prep) || prep.includes('..'))) {
165	          flag('"code_work" reaches outside the task directory (absolute path or "..")', 'reference a sibling script only, e.g. "node prepare.mjs"');
166	        }
167	        if (!hasNum('code_work_timeout', ...LEGACY_CODE_WORK.map(({ timeout }) => timeout))) {
168	          flag('"code_work" is set but declares no numeric "code_work_timeout"', 'add "code_work_timeout": seconds after which the subprocess is killed');
169	        }
170	      }
171	    }
172	    return out;
173	  },
174	};
175	
176	export default rule;
