52	    const findings = run({ [TASK]: bad });
53	    const whats = findings.map((f) => f.what).join(' | ');
54	    assert.match(whats, new RegExp(`"frequency" is "${retired.replace('+', '\\+')}", not a legal value`),
55	      `${retired} is rejected at author time`);
56	    assert.ok(findings.some((f) => f.severity === 'blocking'), `${retired} blocks, not advises`);
