236	  }
237	
238	  // `on_interrupt` — the ack-early/ack-late dial (DESIGN §6). Most of this fleet's
239	  // tasks are sweep-shaped and converge safely on a re-run, so the default is
240	  // `requeue`. A genuinely one-shot side effect (a store submission, an external
241	  // notification) declares `needs-human`, and every recovery path that would
242	  // re-execute it — the leash reclaim, the hand-off retry — converges to triage
243	  // instead: at-most-once plus a human.
244	  if (decl.on_interrupt !== undefined && !INTERRUPT_POLICIES.includes(decl.on_interrupt)) {
245	    bad(`"on_interrupt" ${JSON.stringify(decl.on_interrupt)} is not a legal policy`, `set one of: ${INTERRUPT_POLICIES.join(', ')} (default "requeue")`);
246	  }
247	
248	  // `invocation_endpoint` — a NAME, never a URL (DESIGN §12). The repo's config
249	  // maps the name to the URL and to the name of the Actions secret holding its
250	  // token, so no vendored pack file carries deployment detail or anything adjacent
251	  // to a credential. This is also what replaces session_scope: reach is a property
252	  // of which endpoint a task names.
253	  if (decl.invocation_endpoint !== undefined
254	      && !(typeof decl.invocation_endpoint === 'string' && /^[a-z0-9]+(-[a-z0-9]+)*$/.test(decl.invocation_endpoint))) {
255	    bad('"invocation_endpoint" is not a kebab-case endpoint name', 'name a key from the repo\'s taskScheduler.agenticTaskInvocationEndpoints map, e.g. "fleet" — never a URL');
256	  }
257	
258	  // The repo Actions secrets this task needs configured (DESIGN §9). Purely
259	  // DECLARATIVE — like a pack's adoption `questions`, its job is to drive the ask
260	  // (adoption interactively, the scheduler by owner issue), not to gate anything
261	  // here. So the only shape asserted is "a list of names"; whether the repo has
262	  // actually configured them is a fact about the repo, answered where the secrets
263	  // bundle is readable, never at author time.
264	  if (decl.required_secrets !== undefined
265	      && !(Array.isArray(decl.required_secrets) && decl.required_secrets.every((s) => typeof s === 'string' && s.trim() !== ''))) {
266	    bad('"required_secrets" is not an array of secret names', 'list the repo Actions secret names this task needs, e.g. ["SOME_API_KEY"]');
267	  }
268	
269	  // Execution bound (task-code-work DESIGN §2, §6) — an agentic task MUST
270	  // declare a positive-integer agent_execution_timeout. There is always a bound
271	  // on an agentic run; enforcement is best-effort (the executor surfaces the
272	  // value to the subagent). A `none` task runs no agent, so it needs none.
273	  if (MODEL_FAMILIES.includes(decl.agent_model) && decl.agent_model !== 'none' && !isPositiveInt(decl.agent_execution_timeout)) {
274	    bad('an agentic task (agent_model !== "none") declares no positive-integer "agent_execution_timeout"', 'add "agent_execution_timeout": the seconds bounding the agentic run — generous; extreme protection, not a scheduling knob');
275	  }
276	
277	  // An agentless task (agent_model: none) runs no agent, so its ONLY work is
278	  // code-work — a `none` task with no code-work does nothing (DESIGN §4, retiring
279	  // the in-process inline path). Require the command.
280	  if (decl.agent_model === 'none' && decl.code_work === undefined) {
281	    bad('an agentless task (agent_model: "none") declares no "code_work"', 'add "code_work" (a none task does its work in that subprocess) — or give the task an agent_model');
282	  }
283	
284	  return problems;
285	}
